      id: "note-circulation-030", text: "Which ordered laryngeal-cartilage pair gives one paired type followed by one unpaired cartilage?",
      options: [{ key: "a", text: "Thyroid, then cuneiform" }, { key: "b", text: "Arytenoid, then cricoid" }, { key: "c", text: "Epiglottis, then corniculate" }, { key: "d", text: "Cricoid, then arytenoid" }],
